<?php
$sortUrl = static function (string $key) use ($q, $perPage, $sort, $dir): string { $next = $sort === $key && $dir === 'ASC' ? 'DESC' : 'ASC'; return site_url('admin/users?' . http_build_query(['q'=>$q,'per_page'=>$perPage,'sort'=>$key,'dir'=>$next])); };
$sortIcon = static function (string $key) use ($sort, $dir): string { if ($sort !== $key) return '<i class="bi bi-arrow-down-up kp-muted ms-1" style="font-size:.7rem"></i>'; return $dir === 'ASC' ? '<i class="bi bi-sort-up ms-1"></i>' : '<i class="bi bi-sort-down ms-1"></i>'; };
$start = $total ? (($page - 1) * $perPage) + 1 : 0; $end = min($total, $page * $perPage); $pages = max(1, (int) ceil($total / $perPage));
?>
<?= $this->extend('layouts/admin') ?>
<?= $this->section('content') ?>
<div class="card">
    <div class="card-header d-flex justify-content-between align-items-center"><span><i class="bi bi-person-gear me-1"></i> Manajemen User</span><a class="btn btn-primary btn-sm" href="<?= site_url('admin/users/new') ?>"><i class="bi bi-person-plus me-1"></i> Tambah User</a></div>
    <div class="card-body kp-user-toolbar"><form class="row g-3 align-items-end" method="get"><div class="col-auto"><label class="form-label">Show</label><select class="form-select" name="per_page" onchange="this.form.submit()"><?php foreach([10,25,50] as $n): ?><option value="<?= $n ?>" <?= $perPage===$n?'selected':'' ?>><?= $n ?></option><?php endforeach ?></select></div><div class="col-md-4"><label class="form-label">Search:</label><input class="form-control" name="q" value="<?= esc($q) ?>" placeholder="Email, username, nama"></div><div class="col-auto"><button class="btn btn-primary" type="submit"><i class="bi bi-search me-1"></i> Cari</button></div></form></div>
    <div class="kp-user-table-wrap"><div class="kp-table-wrap"><table class="table align-middle mb-0"><thead><tr><th>No</th><th><a class="kp-sort-link" href="<?= $sortUrl('email') ?>">Email <?= $sortIcon('email') ?></a></th><th><a class="kp-sort-link" href="<?= $sortUrl('username') ?>">Username <?= $sortIcon('username') ?></a></th><th>Role</th><th><a class="kp-sort-link" href="<?= $sortUrl('active') ?>">Status <?= $sortIcon('active') ?></a></th><th class="text-end">Aksi</th></tr></thead><tbody><?php if($users===[]): ?><tr><td colspan="6" class="kp-empty">Belum ada user.</td></tr><?php endif ?><?php foreach($users as $i=>$u): ?><tr><td><?= (($page-1)*$perPage)+$i+1 ?></td><td><?= esc($u['email']) ?></td><td><strong><?= esc($u['username']) ?></strong><?php if($u['full_name']): ?><div class="kp-muted small"><?= esc($u['full_name']) ?></div><?php endif ?></td><td><span class="kp-badge-soft"><?= esc($u['role_name'] ?: '-') ?></span></td><td><?= $u['active'] ? '<span class="badge text-bg-success">Aktif</span>' : '<span class="badge text-bg-secondary">Nonaktif</span>' ?></td><td class="text-end" style="white-space:nowrap"><a class="btn btn-ghost btn-sm" href="<?= site_url('admin/users/'.$u['id'].'/edit') ?>" title="Edit"><i class="bi bi-pencil"></i></a><?php if((int)$u['id'] !== (int)user_id()): ?><form class="d-inline" method="post" action="<?= site_url('admin/users/'.$u['id'].'/reset') ?>" onsubmit="return confirm('Reset password user ini?')"><?= csrf_field() ?><button class="btn btn-ghost btn-sm" title="Reset password"><i class="bi bi-key"></i></button></form><form class="d-inline" method="post" action="<?= site_url('admin/users/'.$u['id'].'/delete') ?>" onsubmit="return confirm('Hapus user ini?')"><?= csrf_field() ?><button class="btn btn-ghost btn-sm text-danger" title="Hapus"><i class="bi bi-trash"></i></button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></div>
    <div class="d-flex justify-content-between align-items-center flex-wrap gap-2 px-3 py-3 small kp-muted"><span>Showing <?= $start ?> to <?= $end ?> of <?= $total ?> entries</span><nav><a class="btn btn-sm btn-ghost <?= $page<=1?'disabled':'' ?>" href="<?= site_url('admin/users?'.http_build_query(['q'=>$q,'per_page'=>$perPage,'sort'=>$sort,'dir'=>$dir,'page_users'=>max(1,$page-1)])) ?>">Previous</a> <span class="mx-2"><?= $page ?> / <?= $pages ?></span><a class="btn btn-sm btn-ghost <?= $page>=$pages?'disabled':'' ?>" href="<?= site_url('admin/users?'.http_build_query(['q'=>$q,'per_page'=>$perPage,'sort'=>$sort,'dir'=>$dir,'page_users'=>min($pages,$page+1)])) ?>">Next</a></nav></div>
</div>
<?= $this->endSection() ?>